import { Schema } from '../../schema';

function 过滤无效出场(data: z.output<typeof Schema>) {
  const 冒险者集合 = new Set(Object.keys(data.冒险者库));
  const 哥布林集合 = new Set(Object.keys(data.哥布林库));
  data.当前遭遇.冒险者出场 = data.当前遭遇.冒险者出场.filter(id => 冒险者集合.has(id));
  data.当前遭遇.哥布林出场 = data.当前遭遇.哥布林出场.filter(id => 哥布林集合.has(id));
  if (
    !data.当前遭遇.焦点对象 ||
    (!冒险者集合.has(data.当前遭遇.焦点对象) && !哥布林集合.has(data.当前遭遇.焦点对象))
  ) {
    data.当前遭遇.焦点对象 = data.当前遭遇.冒险者出场[0] ?? data.当前遭遇.哥布林出场[0] ?? '';
  }
}

function 同步单位派生(data: z.output<typeof Schema>) {
  _.forEach(data.哥布林库, unit => {
    unit.阵营 = '哥布林';
    unit.性别 = '雄';
    unit.标记 = _.uniq([...(unit.标记 ?? []), '巢穴成员']);
  });

  _.forEach(data.冒险者库, unit => {
    unit.阵营 = '冒险者';
  });
}

function 同步遭遇派生(data: z.output<typeof Schema>) {
  const 默认战局标签 = [data.当前遭遇.阶段, data.当前遭遇.主导方, data.当前遭遇.压力等级].filter(Boolean);
  data.当前遭遇.战局标签 = _.uniq(
    (data.当前遭遇.战局标签.length > 0 ? data.当前遭遇.战局标签 : 默认战局标签).filter(Boolean),
  ).slice(0, 6);

  if (!data.当前遭遇.成人后果摘要.trim()) {
    data.当前遭遇.成人后果摘要 = '成人后果尚未进入可结算阶段。';
  }

  if (data.当前遭遇.待决节点.length === 0) {
    data.当前遭遇.待决节点 = ['继续当前遭遇，等待下一轮主导权变化。'];
  }

  data.运行控制.当前推演编号 = data.当前遭遇.编号;
  data.运行控制.状态栏标签 = _.uniq(
    [data.当前遭遇.阶段, data.当前遭遇.主导方, data.当前遭遇.压力等级, data.巢穴.阶段].filter(Boolean),
  ).slice(0, 5);
  data.编年史.当前摘要 = data.当前遭遇.状态摘要 || data.编年史.当前摘要;
}

$(async () => {
  await waitGlobalInitialized('Mvu');

  eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, variables => {
    const raw = _.get(variables, 'stat_data');
    const next = Schema.parse(raw);

    同步单位派生(next);
    过滤无效出场(next);
    同步遭遇派生(next);

    _.set(variables, 'stat_data', Schema.parse(next));
  });
});
