function 归一化文本(value, fallback) {
    if (typeof value === 'string' && value.trim()) {
        return value.trim();
    }
    if (typeof value === 'number' || typeof value === 'boolean') {
        return `${value}`;
    }
    return fallback;
}
function 归一化字符串数组(value, max = 6) {
    if (!Array.isArray(value)) {
        return [];
    }
    return _(value)
        .map(item => 归一化文本(item, ''))
        .filter(Boolean)
        .uniq()
        .take(max)
        .value();
}
function 归一化编号(value, fallback) {
    const raw = 归一化文本(value, fallback)
        .replace(/[^\p{L}\p{N}_-]+/gu, '-')
        .replace(/^-+|-+$/g, '')
        .replace(/-{2,}/g, '-');
    return raw || fallback;
}
const 百分比数值 = (fallback) => z.coerce.number().transform(value => _.clamp(value, 0, 100)).prefault(fallback);
const 非负整数 = (fallback) => z.coerce.number().transform(value => Math.max(0, Math.round(value))).prefault(fallback);
